        # 其余字段（name/type/class/ttl 及范围）由 _validate_levels 按
        # 现有 RR 契约校验，这里仅把十六进制 rdata 转换为 bytes。
        return {"name": rr["name"], "type": rr["type"],
                "class": rr["class"], "ttl": rr["ttl"],
